BEGIN;
-- A finite source graph extends authorized report facts without executing user SQL.
CREATE SCHEMA erp_report_relation_private;
REVOKE ALL ON SCHEMA erp_report_relation_private FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION erp_report_relation_private.edges() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path='' AS $fn$ SELECT $edges$[{"source":"sales","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"business-sales","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"sales-lines","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"sales-payments","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"customer-balances","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"customer-aging","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"customer-credits","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"journal","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"cash-flow","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"expenses","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"receipts","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"credit-charges","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"credit-usages","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"memberships","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"membership-renewals","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"workflows","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"work-orders","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"bookings","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"installments","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"rental-installments","key":"customer","target":"customers","label":"العميل","cardinality":"one","sourceKey":"customerId","targetKey":"id"},{"source":"purchase-documents","key":"supplier","target":"suppliers","label":"المورد","cardinality":"one","sourceKey":"supplierId","targetKey":"id"},{"source":"purchase-lines","key":"supplier","target":"suppliers","label":"المورد","cardinality":"one","sourceKey":"supplierId","targetKey":"id"},{"source":"purchase-payments","key":"supplier","target":"suppliers","label":"المورد","cardinality":"one","sourceKey":"supplierId","targetKey":"id"},{"source":"supplier-balances","key":"supplier","target":"suppliers","label":"المورد","cardinality":"one","sourceKey":"supplierId","targetKey":"id"},{"source":"supplier-aging","key":"supplier","target":"suppliers","label":"المورد","cardinality":"one","sourceKey":"supplierId","targetKey":"id"},{"source":"journal","key":"supplier","target":"suppliers","label":"المورد","cardinality":"one","sourceKey":"supplierId","targetKey":"id"},{"source":"expenses","key":"supplier","target":"suppliers","label":"المورد","cardinality":"one","sourceKey":"supplierId","targetKey":"id"},{"source":"receipts","key":"supplier","target":"suppliers","label":"المورد","cardinality":"one","sourceKey":"supplierId","targetKey":"id"},{"source":"customers","key":"invoices","target":"business-sales","label":"فواتير الأعمال","cardinality":"many","sourceKey":"id","targetKey":"customerId"},{"source":"customers","key":"taxInvoices","target":"sales","label":"الفواتير الضريبية","cardinality":"many","sourceKey":"id","targetKey":"customerId"},{"source":"customers","key":"payments","target":"sales-payments","label":"التحصيلات","cardinality":"many","sourceKey":"id","targetKey":"customerId"},{"source":"customers","key":"memberships","target":"memberships","label":"العضويات","cardinality":"many","sourceKey":"id","targetKey":"customerId"},{"source":"customers","key":"renewals","target":"membership-renewals","label":"التجديدات","cardinality":"many","sourceKey":"id","targetKey":"customerId"},{"source":"customers","key":"charges","target":"credit-charges","label":"شحن الخدمة","cardinality":"many","sourceKey":"id","targetKey":"customerId"},{"source":"customers","key":"usages","target":"credit-usages","label":"استهلاك الخدمة","cardinality":"many","sourceKey":"id","targetKey":"customerId"},{"source":"customers","key":"orders","target":"work-orders","label":"أوامر الشغل","cardinality":"many","sourceKey":"id","targetKey":"customerId"},{"source":"customers","key":"workflows","target":"workflows","label":"دورات العمل","cardinality":"many","sourceKey":"id","targetKey":"customerId"},{"source":"customers","key":"bookings","target":"bookings","label":"المواعيد","cardinality":"many","sourceKey":"id","targetKey":"customerId"},{"source":"customers","key":"installments","target":"installments","label":"الأقساط","cardinality":"many","sourceKey":"id","targetKey":"customerId"},{"source":"suppliers","key":"invoices","target":"purchase-documents","label":"فواتير المورد","cardinality":"many","sourceKey":"id","targetKey":"supplierId"},{"source":"suppliers","key":"payments","target":"purchase-paym