tory","label":"المستودع","cardinality":"one","sourceKey":"warehouseId","targetKey":"id"},{"source":"stock-turnover","key":"item","target":"item-directory","label":"صنف المخزون","cardinality":"one","sourceKey":"productId","targetKey":"id"},{"source":"stock-turnover","key":"warehouse","target":"warehouse-directory","label":"المستودع","cardinality":"one","sourceKey":"warehouseId","targetKey":"id"},{"source":"stock-movements","key":"item","target":"item-directory","label":"صنف المخزون","cardinality":"one","sourceKey":"productId","targetKey":"id"},{"source":"stock-movements","key":"warehouse","target":"warehouse-directory","label":"المستودع","cardinality":"one","sourceKey":"warehouseId","targetKey":"id"},{"source":"stock-requests","key":"item","target":"item-directory","label":"صنف المخزون","cardinality":"one","sourceKey":"productId","targetKey":"id"},{"source":"stock-requests","key":"warehouse","target":"warehouse-directory","label":"المستودع","cardinality":"one","sourceKey":"warehouseId","targetKey":"id"},{"source":"item-directory","key":"balances","target":"stock","label":"أرصدة المستودعات","cardinality":"many","sourceKey":"id","targetKey":"productId"},{"source":"item-directory","key":"movements","target":"stock-movements","label":"حركات المخزون","cardinality":"many","sourceKey":"id","targetKey":"productId"},{"source":"item-directory","key":"requests","target":"stock-requests","label":"أذون المخزون","cardinality":"many","sourceKey":"id","targetKey":"productId"},{"source":"journal","key":"account","target":"accounts","label":"الحساب","cardinality":"one","sourceKey":"accountId","targetKey":"id"},{"source":"cash-flow","key":"account","target":"accounts","label":"الحساب","cardinality":"one","sourceKey":"accountId","targetKey":"id"},{"source":"sales-payments","key":"account","target":"accounts","label":"الحساب","cardinality":"one","sourceKey":"accountId","targetKey":"id"},{"source":"purchase-payments","key":"account","target":"accounts","label":"الحساب","cardinality":"one","sourceKey":"accountId","targetKey":"id"},{"source":"expenses","key":"account","target":"accounts","label":"الحساب","cardinality":"one","sourceKey":"accountId","targetKey":"id"},{"source":"receipts","key":"account","target":"accounts","label":"الحساب","cardinality":"one","sourceKey":"accountId","targetKey":"id"},{"source":"accounts","key":"entries","target":"journal","label":"حركات الحساب","cardinality":"many","sourceKey":"id","targetKey":"accountId"},{"source":"attendance","key":"employee","target":"employees","label":"الموظف","cardinality":"one","sourceKey":"employeeId","targetKey":"id"},{"source":"employee-documents","key":"employee","target":"employees","label":"الموظف","cardinality":"one","sourceKey":"employeeId","targetKey":"id"},{"source":"employee-compliance","key":"employee","target":"employees","label":"الموظف","cardinality":"one","sourceKey":"employeeId","targetKey":"id"},{"source":"leave-balance","key":"employee","target":"employees","label":"الموظف","cardinality":"one","sourceKey":"employeeId","targetKey":"id"},{"source":"contracts","key":"employee","target":"employees","label":"الموظف","cardinality":"one","sourceKey":"employeeId","targetKey":"id"},{"source":"payslips","key":"employee","target":"employees","label":"الموظف","cardinality":"one","sourceKey":"employeeId","targetKey":"id"},{"source":"loans","key":"employee","target":"employees","label":"الموظف","cardinality":"one","sourceKey":"employeeId","targetKey":"id"},{"source":"employees","key":"attendance","target":"attendance","label":"أيام الحضور","cardinality":"many","sourceKey":"id","targetKey":"employeeId"},{"source":"employees","key":"documents","target":"employee-documents","label":"وثائق الموظف","cardinality":"many","sourceKey":"id","targetKey":"employeeId"},{"source":"employees","key":"leave","target":"leave-balance","label":"أرصدة الإجازات","cardinality":"many","sourceKey":"id","targetKey":"employeeId"},{"source":"employees","key":"contracts","target":"contracts","label":"عقود المرتب","card