:"purchase-lines","key":"branch","target":"branch-directory","label":"الفرع المسجل","cardinality":"one","sourceKey":"branchId","targetKey":"id"},{"source":"journal","key":"branch","target":"branch-directory","label":"الفرع المسجل","cardinality":"one","sourceKey":"branchId","targetKey":"id"},{"source":"department-directory","key":"employees","target":"employees","label":"موظفو القسم","cardinality":"many","sourceKey":"id","targetKey":"departmentId"},{"source":"branch-directory","key":"employees","target":"employees","label":"موظفو الفرع","cardinality":"many","sourceKey":"id","targetKey":"branchId"},{"source":"manufacturing","key":"item","target":"item-directory","label":"الصنف الناتج","cardinality":"one","sourceKey":"productId","targetKey":"id"},{"source":"manufacturing","key":"warehouse","target":"warehouse-directory","label":"مستودع الإنتاج","cardinality":"one","sourceKey":"warehouseId","targetKey":"id"}]$edges$::jsonb $fn$;
