CREATE FUNCTION erp_report_relation_private.path(source text,path text) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path='' AS $$
#variable_conflict use_column
DECLARE target text:=source;k text;e jsonb;visited text[]:=ARRAY[source];many boolean:=false;labels text[]:='{}';chain jsonb:='[]';
BEGIN
 IF path!~'^[A-Za-z][A-Za-z0-9_-]*([.][A-Za-z][A-Za-z0-9_-]*){0,2}$' OR length(path)>120 THEN RAISE EXCEPTION 'مسار العلاقة غير صالح';END IF;
 FOREACH k IN ARRAY string_to_array(path,'.') LOOP
  SELECT value INTO e FROM jsonb_array_elements(erp_report_relation_private.edges()) WHERE value->>'source'=target AND value->>'key'=k;
  IF e IS NULL OR e->>'target'=ANY(visited) THEN RAISE EXCEPTION 'العلاقة غير متاحة أو تعيد المصدر نفسه';END IF;
  target:=e->>'target';visited:=array_append(visited,target);many:=many OR e->>'cardinality'='many';labels:=array_append(labels,e->>'label');chain:=chain||jsonb_build_array(e);
 END LOOP;
 RETURN jsonb_build_object('target',target,'cardinality',CASE WHEN many THEN 'many' ELSE 'one' END,'label',array_to_string(labels,' / '),'chain',chain);
END $$;
CREATE FUNCTION erp_report_relation_private.fields(q jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path='' AS $$
#variable_conflict use_column
DECLARE path text;p jsonb;f text;op text;result jsonb:='{}';cols jsonb;
BEGIN
 IF jsonb_typeof(coalesce(q->'relationPaths','[]'))<>'array' OR jsonb_array_length(coalesce(q->'relationPaths','[]'))>8 THEN RAISE EXCEPTION 'يمكن اختيار ثماني علاقات بعمق ثلاثة مستويات';END IF;
 IF jsonb_array_length(coalesce(q->'relationPaths','[]'))<>(SELECT count(DISTINCT v) FROM jsonb_array_elements_text(coalesce(q->'relationPaths','[]'))v) THEN RAISE EXCEPTION 'العلاقات مكررة';END IF;
 FOR path IN SELECT jsonb_array_elements_text(coalesce(q->'relationPaths','[]')) LOOP
  p:=erp_report_relation_private.path(q->>'source',path);
  IF strpos(path,'.')>0 AND NOT(q->'relationPaths'?regexp_replace(path,'[.][^.]+$','')) THEN RAISE EXCEPTION 'اختر العلاقة الأب قبل العلاقة المتداخلة';END IF;
  SELECT columns||'["date","year","quarter","month","week"]'::jsonb INTO cols FROM erp_reports_private.sources WHERE id=p->>'target';
  IF cols IS NULL THEN RAISE EXCEPTION 'مصدر العلاقة غير متاح';END IF;
  IF p->>'cardinality'='many' THEN result:=result||jsonb_build_object(path||'.count',jsonb_build_object('path',path,'source',p->>'target','field','count','operation','count','numeric',true));END IF;
  FOR f IN SELECT DISTINCT jsonb_array_elements_text(cols) LOOP
   IF p->>'cardinality'='one' THEN result:=result||jsonb_build_object(path||'.'||f,jsonb_build_object('path',path,'source',p->>'target','field',f,'operation','one','numeric',f=ANY(erp_reports_private.numeric_fields())));
   ELSIF f<>'count' THEN FOREACH op IN ARRAY CASE WHEN f=ANY(erp_reports_private.numeric_fields()) THEN ARRAY['sum','min','max'] ELSE ARRAY['list'] END LOOP result:=result||jsonb_build_object(path||'.'||op||'.'||f,jsonb_build_object('path',path,'source',p->>'target','field',f,'operation',op,'numeric',op<>'list'));END LOOP;
   END IF;
  END LOOP;
 END LOOP;RETURN result;
END $$;
CREATE FUNCTION erp_report_relation_private.numeric_fields(q jsonb) RETURNS text[] LANGUAGE sql STABLE SET search_path='' AS $$SELECT erp_reports_private.numeric_fields()||coalesce((SELECT array_agg(key) FROM jsonb_each(erp_report_relation_private.fields(q)) WHERE (value->>'numeric')::boolean),'{}')$$;
ALTER FUNCTION erp_reports_private.validate_query(jsonb) RENAME TO validate_query_before_relations;
CREATE FUNCTION erp_reports_private.validate_query(q jsonb) RETURNS void LANGUAGE plpgsql STABLE SET search_path='' AS $$
#variable_conflict use_column
DECLARE f jsonb;allowed jsonb;numerics text[];k text;x jsonb;
BEGIN
 IF NOT(q?'relationPaths') OR q->'relationPaths'='[]'::jsonb THEN PERFORM erp_reports_private.validate_query_before_relations(q);RETURN;END IF;
 f:=erp_report_relation_private.fields(q);numerics:=erp_report_relation_private.numeric_fields(q);
 PERFORM erp_reports_private.validate_query_before_relations(q||'{"columns":["date"],"groupBy":[],"sortBy":"date","conditions":[],"filters":{},"summary":false}'::jsonb);
 SELECT columns||'["date","year","quarter","month","week"]'::jsonb||coalesce((SELECT jsonb_agg(key) FROM jsonb_each(f)),'[]') INTO allowed FROM erp_reports_private.sources WHERE id=q->>'source';
 IF jsonb_typeof(q->'columns') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'columns') NOT BETWEEN 1 AND 40 OR jsonb_typeof(q->'groupBy') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'groupBy')>4 OR jsonb_typeof(q->'conditions') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'conditions')>30 OR jsonb_typeof(q->'filters') IS DISTINCT FROM 'object' OR jsonb_typeof(q->'summary') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع أعمدة التقرير وشروطه وتجميعه';END IF;
 IF jsonb_array_length(q->'columns')<>(SELECT count(DISTINCT x) FROM jsonb_array_elements_text(q->'columns')x) OR jsonb_array_length(q->'groupBy')<>(SELECT count(DISTINCT x) FROM jsonb_array_elements_text(q->'groupBy')x) THEN RAISE EXCEPTION 'أعمدة التقرير أو مجموعاته مكررة';END IF;
 FOR k IN SELECT jsonb_array_elements_text((q->'columns')||(q->'groupBy')||jsonb_build_array(q->>'sortBy')) LOOP IF NOT(allowed?k) THEN RAISE EXCEPTION 'العمود غير متاح في علاقات التقرير المختارة';END IF;END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(q->'groupBy')k WHERE k=ANY(numerics)) OR ((q->>'summary')::boolean AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(q->'columns')k WHERE NOT(k=ANY(numerics)) AND NOT(q->'groupBy'?k))) THEN RAISE EXCEPTION 'راجع حقول التجميع والقيم الرقمية للملخص';END IF;
 FOR x IN SELECT * FROM jsonb_array_elements(q->'conditions') LOOP IF jsonb_typeof(x) IS DISTINCT FROM 'object' OR jsonb_typeof(x->'field') IS DISTINCT FROM 'string' OR jsonb_typeof(x->'value') IS DISTINCT FROM 'string' OR NOT(allowed?(x->>'field')) OR coalesce(x->>'operator','') NOT IN('eq','neq','contains','starts','ends','gte','lte','empty','not_empty') OR length(x->>'value')>1000 THEN RAISE EXCEPTION 'شرط العلاقة غير صالح';END IF;END LOOP;
 FOR k IN SELECT jsonb_object_keys(q->'filters') LOOP IF (NOT(allowed?k) AND k NOT IN('accountClass','accountKind','source','expiry','residency','available','kind','status')) OR jsonb_typeof(q->'filters'->k) IS DISTINCT FROM 'string' OR length(q->'filters'->>k)>1000 THEN RAISE EXCEPTION 'مرشح العلاقة غير صالح';END IF;END LOOP;
END $$;
CREATE FUNCTION erp_report_relation_private.authorize(c uuid,q jsonb) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$
#variable_conflict use_column
DECLARE path text;e jsonb;BEGIN
 PERFORM erp_branch_private.enter(c);PERFORM erp_reports_private.authorize_source(c,q->>'source');
 FOR path IN SELECT jsonb_array_elements_text(coalesce(q->'relationPaths','[]')) LOOP FOR e IN SELECT value FROM jsonb_array_elements(erp_report_relation_private.path(q->>'source',path)->'chain') LOOP PERFORM erp_reports_private.authorize_source(c,e->>'target');END LOOP;END LOOP;
END $$;
-- Only these additional directories are projected; payloads, credentials and files never leave the adapters.
CREATE FUNCTION erp_report_relation_private.directory(c uuid,s text) RETURNS SETOF jsonb LANGUAGE plpgsql SET search_path='' AS $$
#variable_conflict use_column
DECLARE b uuid:=erp_branch_private.current_branch(c);cfg jsonb;BEGIN
 IF s='branch-directory' THEN RETURN QUERY SELECT erp_reports_private.fact(x.id::text,NULL,jsonb_build_object('name',x.name,'number',d.code,'city',x.city,'phone',x.phone,'status',CASE WHEN x.active THEN 'active' ELSE 'inactive' END,'branchId',x.id)) FROM public.branches x LEFT JOIN public.erp_branch_details d ON d.cafe_id=x.cafe_id AND d.id=x.id WHERE x.cafe_id=c AND x.deleted_at IS NULL AND erp_branch_private.branch_allowed(c,x.id) AND(b IS NULL OR x.id=b);
 ELSIF s='item-directory' THEN RETURN QUERY SELECT erp_reports_private.fact(x.id::text,NULL,jsonb_build_object('name',x.name,'number',x.sku,'unit',x.unit,'status',CASE WHEN x.active THEN 'active' ELSE 'inactive' END)) FROM public.bf_items x LEFT JOIN public.erp_inventory_items i ON i.cafe_id=x.cafe_id AND i.item_id=x.id WHERE x.cafe_id=c AND erp_branch_private.allowed_resource(c,b,'item',x.id);
 ELSIF s='warehouse-directory' THEN RETURN QUERY SELECT erp_reports_private.fact(x.id::text,NULL,jsonb_build_object('name',x.name,'status',CASE WHEN x.active THEN 'active' ELSE 'inactive' END)) FROM public.bf_warehouses x WHERE x.cafe_id=c AND erp_inventory_private.warehouse_allowed(c,x.id);
 ELSIF s IN('customer-categories','customer-statuses') THEN RETURN QUERY SELECT erp_reports_private.fact(x.id::text,NULL,jsonb_build_object('name',x.name,'note',x.description,'status',CASE WHEN x.active THEN 'active' ELSE 'inactive' END)) FROM public.erp_customer_catalogs x WHERE x.cafe_id=c AND x.kind=CASE s WHEN 'customer-categories' THEN 'category' ELSE 'status' END;
 ELSIF s='department-directory' THEN RETURN QUERY SELECT erp_reports_private.fact(x.id::text,NULL,jsonb_build_object('name',x.name,'number',coalesce(to_jsonb(x)->>'code',''),'status',CASE WHEN x.active THEN 'active' ELSE 'inactive' END)) FROM public.erp_org_units x WHERE x.cafe_id=c AND x.kind='department';
 ELSIF s='price-lists' THEN cfg:=brand_finance_private.invoice_settings(c);RETURN QUERY SELECT erp_reports_private.fact(x->>'id',NULL,jsonb_build_object('name',x->>'name','status',CASE WHEN(x->>'active')::boolean THEN 'active' ELSE 'inactive' END)) FROM jsonb_array_elements(coalesce(cfg#>'{advanced,priceLists}','[]'))x WHERE coalesce((cfg#>>'{advanced,priceListsEnabled}')::boolean,false);
 ELSE RAISE EXCEPTION 'دليل العلاقة غير متاح';END IF;RETURN;
END $$;
-- Preserve the existing branch + business-sales wrappers and public RPC OIDs.
DO $$DECLARE def text;BEGIN SELECT pg_get_functiondef('erp_reports_private.facts(uuid,text,date,date)'::regprocedure) INTO def;EXECUTE replace(def,'erp_reports_private.facts(','erp_report_relation_private.facts_before_relations(');END $$;
CREATE OR REPLACE FUNCTION erp_reports_private.facts(c uuid,s text,f date,t date) RETURNS SETOF jsonb LANGUAGE plpgsql SET search_path='' AS $$
#variable_conflict use_column
DECLARE r jsonb;b uuid;BEGIN
 IF s=ANY(ARRAY['branch-directory','item-directory','warehouse-directory','customer-categories','customer-statuses','price-lists','department-directory']) THEN
  PERFORM erp_branch_private.enter(c);PERFORM erp_reports_private.authorize_source(c,s);b:=erp_branch_private.current_branch(c);
  FOR r IN SELECT * FROM erp_report_relation_private.directory(c,s) LOOP IF erp_branch_private.row_allowed(c,b,r,'') THEN RETURN NEXT r;END IF;END LOOP;
 ELSE RETURN QUERY SELECT * FROM erp_report_relation_private.facts_before_relations(c,s,f,t);END IF;RETURN;
END $$;
CREATE FUNCTION erp_report_relation_private.keys(c uuid,s text,r jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path='' AS $$
#variable_conflict use_column
DECLARE extra jsonb:='{}';d uuid;ref uuid;profile jsonb;resource text;b uuid:=erp_branch_private.current_branch(c);
BEGIN
 -- Real foreign keys only: names and display numbers are never join keys.
 IF s IN('sales','business-sales','purchase-documents') THEN d:=(r->>'id')::uuid;
 ELSIF s IN('sales-lines','purchase-lines') THEN SELECT document_id INTO d FROM public.bf_document_lines WHERE cafe_id=c AND id::text=r->>'id';SELECT CASE WHEN kind='refund' THEN reference_id ELSE id END INTO ref FROM public.bf_documents WHERE cafe_id=c AND id=d;extra:=extra||jsonb_build_object('documentId',d,'invoiceId',ref);
 ELSIF s IN('journal','cash-flow','sales-payments','purchase-payments') THEN SELECT document_id INTO d FROM public.bf_journal WHERE cafe_id=c AND id::text=r->>'id';SELECT CASE WHEN kind IN('sale','purchase') THEN id ELSE reference_id END INTO ref FROM public.bf_documents WHERE cafe_id=c AND id=d;extra:=extra||jsonb_build_object('invoiceId',ref,'documentId',d);
 ELSIF s='customers' THEN
  SELECT erp_customer_private.profile(p) INTO profile FROM public.bf_parties p WHERE cafe_id=c AND id::text=r->>'id';
  extra:=jsonb_build_object('categoryIds',coalesce(profile->'categories','[]'),'statusId',profile->'statusId','assignedUserId',profile->'assignedUserId','priceListId',(SELECT price_list_id FROM public.erp_customer_portal_links WHERE cafe_id=c AND customer_id::text=r->>'id'));
 ELSIF s='employees' THEN extra:=jsonb_build_object('userId',(SELECT user_id FROM public.erp_hr_employees WHERE cafe_id=c AND id::text=r->>'id'));
 ELSIF s='manufacturing' THEN SELECT jsonb_build_object('productId',o.payload->>'productId','warehouseId',(SELECT warehouse_id FROM public.bf_documents WHERE cafe_id=c AND id=o.output_document_id)) INTO extra FROM public.erp_mfg_orders o WHERE cafe_id=c AND id::text=r->>'id';
 END IF;
 IF d IS NOT NULL THEN extra:=extra||jsonb_build_object('branchId',(SELECT branch_id FROM public.erp_branch_documents WHERE cafe_id=c AND document_id=d));END IF;
 IF s IN('customers','customer-aging','customer-credits') AND coalesce(r->>'customerId','')='' AND r->>'id'~'^[0-9a-f-]{36}$' THEN extra:=extra||jsonb_build_object('customerId',r->>'id');END IF;
 IF s IN('suppliers','supplier-aging') THEN extra:=extra||jsonb_build_object('supplierId',r->>'id');END IF;
 resource:=CASE s WHEN 'customers' THEN 'customer' WHEN 'suppliers' THEN 'supplier' WHEN 'item-directory' THEN 'item' WHEN 'accounts' THEN 'account' END;
 IF resource IS NOT NULL THEN extra:=extra||jsonb_build_object('branchIds',coalesce((SELECT jsonb_agg(branch_id) FROM public.erp_branch_resources WHERE cafe_id=c AND kind=resource AND record_id::text=r->>'id' AND(b IS NULL OR branch_id=b) AND erp_branch_private.branch_allowed(c,branch_id)),'[]'));END IF;
 RETURN r||coalesce(extra,'{}');
END $$;
CREATE FUNCTION erp_report_relation_private.dataset(c uuid,s text,f date,t date,include_history boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $$
#variable_conflict use_column
DECLARE rows jsonb;BEGIN
 PERFORM erp_reports_private.authorize_source(c,s);
 SELECT coalesce(jsonb_agg(erp_reports_private.enrich(erp_report_relation_private.keys(c,s,x))),'[]') INTO rows FROM(SELECT x FROM erp_reports_private.facts(c,s,f,t)x WHERE include_history OR x->>'date' IS NULL OR(x->>'date')::date BETWEEN f AND t LIMIT 5001)q;
 IF jsonb_array_length(rows)>5000 THEN RAISE EXCEPTION 'تجاوز مصدر العلاقات خمسة آلاف سجل حدد فترة أصغر' USING ERRCODE='54000';END IF;RETURN rows;
END $$;
CREATE FUNCTION erp_report_relation_private.metric(rows jsonb,field text,operation text,source text) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path='' AS $$
#variable_conflict use_column
DECLARE value jsonb;BEGIN
 IF operation='count' THEN RETURN to_jsonb(jsonb_array_length(rows));END IF;
 IF operation='list' THEN SELECT to_jsonb(coalesce(string_agg(v,'، ' ORDER BY v),'')) INTO value FROM(SELECT DISTINCT x->>field v FROM jsonb_array_elements(rows)x WHERE coalesce(x->>field,'')<>'')q;IF length(value#>>'{}')>10000 THEN RAISE EXCEPTION 'قائمة العلاقة طويلة حدد شروطًا أدق' USING ERRCODE='54000';END IF;RETURN value;END IF;
 IF operation='one' THEN IF jsonb_array_length(rows)>1 THEN RAISE EXCEPTION 'علاقة السجل المفرد أعادت عدة سجلات';END IF;RETURN coalesce(rows->0->field,'null');END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(rows)x WHERE x->field='null'::jsonb) THEN RETURN 'null';END IF;
 IF operation='sum' THEN SELECT to_jsonb(coalesce(sum((x->>field)::numeric),0)) INTO value FROM jsonb_array_elements(rows)x WHERE jsonb_typeof(x->field)='number';RETURN value;END IF;
 SELECT CASE operation WHEN 'min' THEN to_jsonb(min((x->>field)::numeric)) WHEN 'max' THEN to_jsonb(max((x->>field)::numeric)) END INTO value FROM jsonb_array_elements(rows)x WHERE jsonb_typeof(x->field)='number';RETURN coalesce(value,'null');
END $$;
CREATE FUNCTION erp_report_relation_private.aggregate(records jsonb[],key text,q jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path='' AS $$
#variable_conflict use_column
DECLARE spec jsonb:=erp_report_relation_private.fields(q)->key;rows jsonb;BEGIN
 IF spec IS NULL THEN RETURN erp_reports_private.aggregate_metric(records,key,q->>'source');END IF;
 SELECT coalesce(jsonb_agg(x),'[]') INTO rows FROM(SELECT DISTINCT ON(x->>'id') x FROM unnest(records)r CROSS JOIN LATERAL jsonb_array_elements(coalesce(r#>ARRAY['_relationRows',spec->>'path'],'[]'))x ORDER BY x->>'id')u;
 RETURN erp_report_relation_private.metric(rows,spec->>'field',CASE spec->>'operation' WHEN 'one' THEN 'sum' ELSE spec->>'operation' END,spec->>'source');
END $$;
CREATE FUNCTION erp_report_relation_private.matches(r jsonb,q jsonb) RETURNS boolean LANGUAGE plpgsql STABLE SET search_path='' AS $$
#variable_conflict use_column
DECLARE x jsonb;k text;v text;matched boolean;any_match boolean:=false;numerics text[]:=erp_report_relation_private.numeric_fields(q);BEGIN
 FOR k,v IN SELECT key,value FROM jsonb_each_text(q->'filters') LOOP IF v<>'' AND coalesce(r->>k,'')<>v THEN RETURN false;END IF;END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(q->'conditions') LOOP k:=x->>'field';v:=x->>'value';
  IF k=ANY(numerics) AND x->>'operator' IN('gte','lte') THEN IF v!~'^-?[0-9]+([.][0-9]+)?$' THEN RAISE EXCEPTION 'قيمة شرط العلاقة ليست رقمًا';END IF;matched:=coalesce(CASE x->>'operator' WHEN 'gte' THEN(r->>k)::numeric>=v::numeric ELSE(r->>k)::numeric<=v::numeric END,false);
  ELSE matched:=coalesce(erp_reports_private.condition(r,x),false);END IF;
  IF q->>'conditionMode'='all' AND NOT matched THEN RETURN false;END IF;any_match:=any_match OR matched;
 END LOOP;RETURN q->>'conditionMode'<>'any' OR jsonb_array_length(q->'conditions')=0 OR any_match;
END $$;

CREATE FUNCTION erp_report_relation_private.prepare(c uuid,q jsonb) RETURNS SETOF jsonb LANGUAGE plpgsql SET search_path='' AS $$
#variable_conflict use_column
DECLARE all_fields jsonb:=erp_report_relation_private.fields(q);pool jsonb:='{}';indexes jsonb:='{}';datasets text[]:=ARRAY[q->>'source'];historical text[]:='{}';source text;path text;spec jsonb;e jsonb;rows jsonb;idx jsonb;r jsonb;result jsonb;linked jsonb;parents jsonb;parent_path text;last_edge jsonb;keys text[];field record;selected text[];n integer:=0;traversals integer:=0;
BEGIN
 PERFORM erp_report_relation_private.authorize(c,q);
 SELECT array_agg(DISTINCT key) INTO selected FROM(SELECT jsonb_array_elements_text((q->'columns')||(q->'groupBy')||jsonb_build_array(q->>'sortBy')) key UNION SELECT jsonb_object_keys(q->'filters') UNION SELECT value->>'field' FROM jsonb_array_elements(q->'conditions'))v;
 FOR path IN SELECT jsonb_array_elements_text(q->'relationPaths') LOOP FOR e IN SELECT value FROM jsonb_array_elements(erp_report_relation_private.path(q->>'source',path)->'chain') LOOP IF e->>'cardinality'='one' THEN historical:=array_append(historical,e->>'target');END IF;IF NOT(e->>'target'=ANY(datasets)) THEN datasets:=array_append(datasets,e->>'target');END IF;END LOOP;END LOOP;
 FOREACH source IN ARRAY datasets LOOP
  rows:=erp_report_relation_private.dataset(c,source,(q->>'from')::date,(q->>'to')::date,source=ANY(historical));n:=n+jsonb_array_length(rows);IF n>20000 THEN RAISE EXCEPTION 'تجاوزت مصادر العلاقات عشرين ألف سجل حدد فترة أو مصادر أقل' USING ERRCODE='54000';END IF;
  pool:=pool||jsonb_build_object(source,rows);
 END LOOP;
 IF octet_length(pool::text)>20000000 THEN RAISE EXCEPTION 'حجم بيانات العلاقات كبير حدد فترة أصغر' USING ERRCODE='54000';END IF;
 FOR e IN SELECT DISTINCT value FROM jsonb_array_elements(erp_report_relation_private.edges()) WHERE value->>'source'=ANY(datasets) AND value->>'target'=ANY(datasets) LOOP
  SELECT coalesce(jsonb_object_agg(k,rs),'{}') INTO idx FROM(SELECT x->>(e->>'targetKey') k,jsonb_agg(x) rs FROM jsonb_array_elements(pool->(e->>'target'))x WHERE coalesce(x->>(e->>'targetKey'),'')<>'' GROUP BY 1)v;
  indexes:=indexes||jsonb_build_object((e->>'target')||':'||(e->>'targetKey'),idx);
 END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(pool->(q->>'source')) WHERE value->>'date' IS NULL OR(value->>'date')::date BETWEEN(q->>'from')::date AND(q->>'to')::date LOOP
  result:=r||'{"_relationRows":{}}'::jsonb;
  FOR path IN SELECT value FROM jsonb_array_elements_text(q->'relationPaths')v(value) ORDER BY length(value),value LOOP
   spec:=erp_report_relation_private.path(q->>'source',path);last_edge:=spec->'chain'->-1;parent_path:=CASE WHEN strpos(path,'.')>0 THEN regexp_replace(path,'[.][^.]+$','') ELSE '' END;
   parents:=CASE WHEN parent_path='' THEN jsonb_build_array(r) ELSE result#>ARRAY['_relationRows',parent_path] END;
   SELECT array_agg(DISTINCT k) INTO keys FROM jsonb_array_elements(parents)p CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(p->(last_edge->>'sourceKey'))='array' THEN p->(last_edge->>'sourceKey') ELSE jsonb_build_array(p->(last_edge->>'sourceKey')) END)k WHERE k IS NOT NULL AND k<>'';
   SELECT coalesce(jsonb_agg(x),'[]') INTO linked FROM(SELECT DISTINCT ON(x->>'id') x FROM unnest(keys)k CROSS JOIN LATERAL jsonb_array_elements(coalesce(indexes#>ARRAY[(last_edge->>'target')||':'||(last_edge->>'targetKey'),k],'[]'))x WHERE last_edge->>'cardinality'='one' OR x->>'date' IS NULL OR(x->>'date')::date BETWEEN(q->>'from')::date AND(q->>'to')::date ORDER BY x->>'id')v;
   traversals:=traversals+jsonb_array_length(linked);IF traversals>100000 THEN RAISE EXCEPTION 'العلاقات كثيرة حدد شروط المصدر أو فترة أصغر' USING ERRCODE='54000';END IF;
   IF spec->>'cardinality'='one' AND jsonb_array_length(linked)>1 THEN RAISE EXCEPTION 'علاقة مفردة غير متسقة مع بيانات المصدر';END IF;
   result:=jsonb_set(result,ARRAY['_relationRows',path],linked);
   FOR field IN SELECT key,value FROM jsonb_each(all_fields) WHERE value->>'path'=path AND key=ANY(selected) LOOP result:=result||jsonb_build_object(field.key,erp_report_relation_private.metric(linked,field.value->>'field',field.value->>'operation',field.value->>'source'));END LOOP;
  END LOOP;
  RETURN NEXT result;
 END LOOP;RETURN;
END $$;
-- Clone the reviewed renderer, replacing only its data/metric/condition providers.
DO $$DECLARE def text;original text;BEGIN
 SELECT pg_get_functiondef('erp_reports_private.run(uuid,jsonb,boolean)'::regprocedure) INTO def;
 EXECUTE replace(def,'erp_reports_private.run(','erp_report_relation_private.run_before_relations(');
 original:='SELECT erp_reports_private.enrich(x) r FROM erp_reports_private.facts(p_cafe_id,q->>''source'',(q->>''from'')::date,(q->>''to'')::date)x';
 IF strpos(def,original)=0 THEN RAISE EXCEPTION 'Report renderer changed before relation integration';END IF;
 def:=replace(def,'erp_reports_private.run(','erp_report_relation_private.run(');
 def:=replace(def,original,'SELECT x r FROM erp_report_relation_private.prepare(p_cafe_id,q)x');
 def:=replace(def,'erp_reports_private.matches(r,q)','erp_report_relation_private.matches(r,q)');
 def:=replace(def,'erp_reports_private.numeric_fields()','erp_report_relation_private.numeric_fields(q)');
 def:=replace(def,'erp_reports_private.aggregate_metric(records,k,q->>''source'')','erp_report_relation_private.aggregate(records,k,q)');
 def:=replace(def,'erp_reports_private.aggregate_metric((SELECT array_agg(r) FROM filtered),k,q->>''source'')','erp_report_relation_private.aggregate((SELECT array_agg(r) FROM filtered),k,q)');
 def:=replace(def,'(SELECT columns FROM erp_reports_private.sources WHERE id=q->>''source'')','(q->''columns'')');
 def:=replace(def,'''basis'',''real_source_records''','''basis'',''related_source_records_distinct_targets''');
 EXECUTE def;
END $$;
CREATE OR REPLACE FUNCTION erp_reports_private.run(p_cafe_id uuid,p_query jsonb,p_export boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN
 PERFORM erp_reports_private.validate_query(p_query);
 IF jsonb_array_length(coalesce(p_query->'relationPaths','[]'))=0 THEN RETURN erp_report_relation_private.run_before_relations(p_cafe_id,p_query,p_export);END IF;
 RETURN erp_report_relation_private.run(p_cafe_id,p_query,p_export);
END $$;
CREATE FUNCTION erp_report_relation_private.visible(c uuid,q jsonb) RETURNS boolean LANGUAGE plpgsql SET search_path='' AS $$BEGIN PERFORM erp_report_relation_private.authorize(c,q);RETURN true;EXCEPTION WHEN insufficient_privilege THEN RETURN false;END $$;
DO $$DECLARE def text;BEGIN
 SELECT pg_get_functiondef('public.erp_reports_read(uuid)'::regprocedure) INTO def;EXECUTE replace(def,'public.erp_reports_read(','erp_report_relation_private.read_before_relations(');
 SELECT pg_get_functiondef('public.erp_reports_write(uuid,text,jsonb,uuid)'::regprocedure) INTO def;EXECUTE replace(def,'public.erp_reports_write(','erp_report_relation_private.write_before_relations(');
END $$;
CREATE OR REPLACE FUNCTION public.erp_reports_read(p_cafe_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
#variable_conflict use_column
DECLARE result jsonb;BEGIN
 result:=erp_report_relation_private.read_before_relations(p_cafe_id);
 result:=jsonb_set(result,'{saved}',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(result->'saved')x WHERE erp_report_relation_private.visible(p_cafe_id,x->'query')),'[]'));
 RETURN result||jsonb_build_object('relations',jsonb_build_object('version',1,'maxDepth',3,'maxPaths',8,'maxSourceRows',5000,'maxTotalRows',20000,'edges',coalesce((SELECT jsonb_agg(e-'sourceKey'-'targetKey') FROM jsonb_array_elements(erp_report_relation_private.edges())e WHERE erp_reports_private.visible_source(p_cafe_id,e->>'source') AND erp_reports_private.visible_source(p_cafe_id,e->>'target')),'[]')));
END $$;
CREATE OR REPLACE FUNCTION public.erp_reports_write(p_cafe_id uuid,p_action text,p_data jsonb,p_request_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
#variable_conflict use_column
DECLARE oldq jsonb;BEGIN
 IF p_action='save' THEN PERFORM erp_reports_private.validate_query(p_data->'query');PERFORM erp_report_relation_private.authorize(p_cafe_id,p_data->'query');END IF;
 IF p_data->>'id' IS NOT NULL THEN SELECT definition->'query' INTO oldq FROM public.erp_saved_reports WHERE cafe_id=p_cafe_id AND id=(p_data->>'id')::uuid;IF oldq IS NOT NULL THEN PERFORM erp_report_relation_private.authorize(p_cafe_id,oldq);END IF;END IF;
 RETURN erp_report_relation_private.write_before_relations(p_cafe_id,p_action,p_data,p_request_id);
END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA erp_report_relation_private FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION erp_reports_private.validate_query(jsonb),erp_reports_private.validate_query_before_relations(jsonb),erp_reports_private.facts(uuid,text,date,date),erp_reports_private.run(uuid,jsonb,boolean) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.erp_reports_read(uuid),public.erp_reports_write(uuid,text,jsonb,uuid) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.erp_reports_read(uuid),public.erp_reports_write(uuid,text,jsonb,uuid) TO authenticated;
COMMIT;
